import{_ as o,o as r,c as e,ai as d}from"./chunks/framework.CAnUr3M0.js";const p=JSON.parse('{"title":"网络安全","description":"","frontmatter":{},"headers":[],"relativePath":"browser/security.md","filePath":"browser/security.md"}'),i={name:"browser/security.md"};function a(l,t,n,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="网络安全" tabindex="-1">网络安全 <a class="header-anchor" href="#网络安全" aria-label="Permalink to &quot;网络安全&quot;">​</a></h1><blockquote><p>XSS（跨站脚本攻击） · CSRF（跨站请求伪造） · 防御策略</p></blockquote><hr><h2 id="一、xss-跨站脚本攻击" tabindex="-1">一、XSS（跨站脚本攻击） <a class="header-anchor" href="#一、xss-跨站脚本攻击" aria-label="Permalink to &quot;一、XSS（跨站脚本攻击）&quot;">​</a></h2><p><strong>本质</strong>：代码注入攻击，攻击者在目标网站注入恶意脚本在用户浏览器执行</p><p><strong>三种类型</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>存储区</th><th>触发方式</th></tr></thead><tbody><tr><td>存储型（持久性）</td><td>后端数据库</td><td>无需用户手动触发，最危险</td></tr><tr><td>反射型（非持久性）</td><td>URL</td><td>需用户点击恶意链接</td></tr><tr><td>DOM 型</td><td>URL/前端存储</td><td>前端 JS 取出恶意代码执行</td></tr></tbody></table><p><strong>防御</strong>：</p><ol><li><strong>HttpOnly Cookie</strong>：JS 无法读取 Cookie</li><li><strong>输入过滤</strong>：前后端都做输入格式校验</li><li><strong>HTML 转义</strong>：对 <code>&lt; &gt; &quot; &#39; &amp; /</code> 等特殊字符转义</li><li><strong>白名单过滤</strong>：富文本场景用白名单而非黑名单</li><li><strong>纯前端渲染</strong>：用 <code>.innerText</code> / <code>.setAttribute()</code> 代替 <code>.innerHTML</code></li><li><strong>避免危险 API</strong>：不使用 <code>eval()</code>、<code>innerHTML</code>、<code>document.write()</code></li></ol><hr><h2 id="二、csrf-跨站请求伪造" tabindex="-1">二、CSRF（跨站请求伪造） <a class="header-anchor" href="#二、csrf-跨站请求伪造" aria-label="Permalink to &quot;二、CSRF（跨站请求伪造）&quot;">​</a></h2><p><strong>本质</strong>：利用浏览器自动携带 Cookie 的特性，冒充已登录用户发起请求</p><p><strong>攻击流程</strong>：</p><ol><li>用户登录网站 A，本地生成 Cookie</li><li>用户在不登出 A 的情况下访问恶意网站 B</li><li>网站 B 向网站 A 发起请求，浏览器自动携带 A 的 Cookie</li><li>网站 A 认为是合法用户操作，执行请求</li></ol><p><strong>CSRF vs XSS</strong>：</p><table tabindex="0"><thead><tr><th></th><th>XSS</th><th>CSRF</th></tr></thead><tbody><tr><td>本质</td><td>代码注入问题</td><td>HTTP 请求问题</td></tr><tr><td>攻击方式</td><td>注入恶意代码并执行</td><td>冒用用户身份发起请求</td></tr><tr><td>目标</td><td>窃取数据/注入内容</td><td>执行非预期操作</td></tr></tbody></table><p><strong>防御</strong>：</p><ol><li><strong>Token 验证</strong>（最推荐）：请求中携带随机 Token，服务端校验</li><li><strong>SameSite Cookie</strong>：限制 Cookie 只在同站请求中发送</li><li><strong>Referer/Origin 检查</strong>：校验请求来源域名</li><li><strong>验证码</strong>：强制用户交互</li></ol><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./network.html">网络协议与缓存</a> — Cookie/Session/Token 机制</li><li><a href="./html.html">HTML 基础</a> — localStorage、httpOnly 属性</li></ul>',21)])])}const S=o(i,[["render",a]]);export{p as __pageData,S as default};
